questionvariables.text:
/* isfun=1: an upward parabola (a function).
   isfun=0: a sideways parabola x = 0.4*a*y^2 - 3 (fails the vertical line test). */
isfun: rand([0, 1]);
a: rand([1, 2]);
ta1: [[isfn, is(isfun=1), "represents a function"], [notfn, is(isfun=0), "does not represent a function"]];
tac1: first(mcq_correct(ta1));
